  "brain.py": "\"\"\"No-orchestrator brain - peers claim work by trace-id hash.\n\n    python brain.py poems\n\nThere is no cortex and no queue group. Every peer sees every TASK for\n\"pool\", runs the same pure function over its trace_id, and only the owner\nanswers. Adding a peer is adding an id to PEERS.\n\"\"\"\nimport asyncio\nimport contextlib\nimport hashlib\nimport signal\n\nfrom cosmonapse import Dendrite, MemorySynapse, connect_synapse, run_brain\n\nfrom config import NAMESPACE, PEERS, SYNAPSE_URL\nfrom neurons import pool\nfrom receptors import terminal\n\n\ndef owner_of(trace_id: str) -> str:\n    \"\"\"Pure function: every peer computes the SAME owner - no coordination.\"\"\"\n    h = int(hashlib.sha1(trace_id.encode()).hexdigest(), 16)\n    return PEERS[h % len(PEERS)]\n\n\ndef build_peer(synapse, peer_id: str) -> Dendrite:\n    axon = pool.make_axon(peer_id)\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=peer_id, role=\"worker\", heartbeat_s=0)\n\n    @node.on_task_signal(neuron=\"pool\")\n    async def claim(task):\n        if owner_of(task.trace_id) != peer_id:\n            return                                   # a peer owns this one\n        reply = await axon.handle_task(task)         # AGENT_OUTPUT / ERROR\n        # The Dendrite never routed this TASK to an attached Axon, so the\n        # reply goes out on the synapse directly.\n        await synapse.publish(f\"cosmonapse.{NAMESPACE}.{reply.type.value}\", reply)\n\n    return node\n\n\ndef build_terminal(synapse) -> Dendrite:\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"terminal-node\", heartbeat_s=0)\n    node.attach_receptor(terminal.RECEPTOR)\n    return node\n\n\ndef _stop_on_signals() -> None:\n    \"\"\"Ctrl-C / SIGTERM cancel the task so run_brain can unwind every node.\"\"\"\n    task = asyncio.current_task()\n    loop = asyncio.get_running_loop()\n    for sig in (signal.SIGINT, signal.SIGTERM):\n        with contextlib.suppress(NotImplementedError, AttributeError):\n            loop.add_signal_handler(sig, task.cancel)\n\n\nasync def main() -> int:\n    _stop_on_signals()\n    if SYNAPSE_URL:\n        synapse = await connect_synapse(SYNAPSE_URL)\n    else:\n        synapse = MemorySynapse()      # in-process bus - no broker, no setup\n        await synapse.connect()\n    try:\n        return await run_brain(\n            *(build_peer(synapse, p) for p in PEERS),\n            build_terminal(synapse),\n        )\n    except asyncio.CancelledError:\n        return 0\n    finally:\n        await synapse.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(asyncio.run(main()))\n    except KeyboardInterrupt:\n        raise SystemExit(130)\n",
