  "neurons/pool.py": "\"\"\"pool - N identical HF chat Neurons, one per peer.\n\nThe Axon is NOT attached to a Dendrite. Nothing addresses a peer by id:\nwork arrives addressed to \"pool\", and each peer decides by hash whether it\nis the owner (see brain.build_peer), then calls axon.handle_task itself.\n\"\"\"\nfrom cosmonapse import Axon, Neuron\n\nfrom config import hf_token\n\n\ndef make_axon(neuron_id: str) -> Axon:\n    return Axon(\n        neuron_id=neuron_id,\n        neuron_fn=Neuron(\n            source=\"huggingface\",\n            endpoint=\"https://router.huggingface.co\",\n            model=\"meta-llama/Llama-3.1-8B-Instruct\",\n            api_key=hf_token(),\n            use_chat_api=True,\n            max_new_tokens=128,\n        ),\n        capabilities=[\"chat\"],\n    )\n",
  "receptors/terminal.py": "\"\"\"terminal - drops work in and routes nothing.\n\n    python brain.py \"the sun\"\n    python brain.py poems                 # four prompts; watch who claims each\n\nThe TASK is addressed to \"pool\", which no Axon is attached as. The peers\ndecide among themselves who answers; the Receptor just waits on the trace\nand reports which peer's AGENT_OUTPUT came back.\n\"\"\"\nfrom cosmonapse import CliReceptor, SignalType\n\nRECEPTOR = CliReceptor(\n    neuron=\"pool\",\n    prog=\"no-orchestrator\",\n    description=\"Peers claim work by trace-id hash.\",\n    timeout_s=60.0,\n)\n\n\n@RECEPTOR.command(help=\"drop a prompt into the pool\")\ndef ask(prompt: str):\n    return {\"prompt\": prompt}\n\n\n@RECEPTOR.command(\"poems\", local=True, help=\"four prompts, see who claims each\")\nasync def poems():\n    topics = (\"the sun\", \"the moon\", \"the sea\", \"the wind\")\n    return \"\\n\".join([await RECEPTOR.ask({\"prompt\": t}) for t in topics])\n\n\n@RECEPTOR.on_result\ndef render(sig):\n    who = sig.directed.id if sig.directed else \"?\"\n    if sig.type is SignalType.ERROR:\n        return f\"{who} failed: {sig.payload.get('message')}\"\n    return f\"{who} answered: {sig.payload['output']['response'].strip()}\"\n"
